search.service.d cat &gt; /etc/systemd/system/elasticsearch.service.d/override.conf &lt;&lt; EOF [Service] LimitNOFILE=65536 LimitNPROC=4096 LimitMEMLOCK=infinity EOF systemctl daemon-reload log &#34;文件描述符限制优化完成&#34; } # 优化虚拟内存 optimize_virtual_memory() { log &#34;优化虚拟内存设置...&#34; # 设置vm.max_map_count echo &#39;vm.max_map_count=262144&#39; &gt;&gt; /etc/sysctl.conf sysctl -p # 设置swappiness echo &#39;vm.swappiness=1&#39; &gt;&gt; /etc/sysctl.conf sysctl -p log &#34;虚拟内存优化完成&#34; } # 优化磁盘I/O optimize_disk_io() { log &#34;优化磁盘I/O设置...&#34; # 获取数据磁盘设备 DATA_DEVICES=$(lsblk -no NAME,MOUNTPOINT | grep &#39;/data&#39; | awk &#39;{print $1}&#39; | sed &#39;s/[0-9]*$//&#39;) for device in $DATA_DEVICES; do if [ -b &#34;/dev/$device&#34; ]; then # 设置I/O调度器为deadline或noop echo deadline &gt; /sys/block/$device/queue/scheduler # 设置读取预读 echo 128 &gt; /sys/block/$device/queue/read_ahead_kb # 设置队列深度 echo 32 &gt; /sys/block/$device/queue/nr_requests log &#34;已优化设备 /dev/$device 的I/O设置&#34; fi done } # 优化网络设置 optimize_network() { log &#34;优化网络设置...&#34; cat &gt;&gt; /etc/sysctl.conf &lt;&lt; EOF # 网络优化 net.core.rmem_default = 262144 net.core.rmem_max = 16777216 net.core.wmem_default = 262144 net.core.wmem_max = 16777216 net.ipv4.tcp_rmem = 4096 65536 16777216 net.ipv4.tcp_wmem = 4096 65536 16777216 net.core.netdev_max_backlog = 5000 net.ipv4.tcp_congestion_control = bbr EOF sysctl -p log &#34;网络优化完成&#34; } # 创建监控脚本 create_monitoring_script() { log &#34;创建系统监控脚本...&#34; cat &gt; /usr/local/bin/elasticsearch_system_monitor.sh &lt;&lt; &#39;EOF&#39; #!/bin/bash # Elasticsearch系统监控脚本 # 检查JVM堆内存使用 check_jvm_memory() { local es_host=&#34;${1:-localhost:9200}&#34; curl -s &#34;$es_host/_nodes/stats/jvm&#34; | jq -r &#39; .nodes[] | &#34;节点: &#34; + .name + &#34; | 堆内存使用: &#34; + (.jvm.mem.heap_used_percent | tostring) + &#34;%&#34; + &#34; | GC次数: &#34; + (.jvm.gc.collectors.young.collection_count | tostring) &#39; } # 检查磁盘使用情况 check_disk_usage() { local es_host=&#34;${1:-localhost:9200}&#34; curl -s &#34;$es_host/_nodes/stats/fs&#34; | jq -r &#39; .nodes[] | &#34;节点: &#34; + .name + &#34; | 磁盘使用: &#34; + ((.fs.total.total_in_bytes - .fs.total.available_in_bytes) * 100 / .fs.total.total_in_bytes | floor | tostring) + &#34;%&#34; &#39; } # 检查查询性能 check_query_performance() { local es_host=&#34;${1:-localhost:9200}&#34; curl -s &#34;$es_host/_nodes/stats/indices/search&#34; | jq -r &#39; .nodes[] | &#34;节点: &#34; + .name + &#34; | 查询总数: &#34; + (.indices.search.query_total | tostring) + &#34; | 平均查询时间: &#34; + ((.indices.search.query_time_in_millis / .indices.search.query_total) | floor | tostring) + &#34;ms&#34; &#39; } # 检查集群健康状态 check_cluster_health() { local es_host=&#34;${1:-localhost:9200}&#34; curl -s &#34;$es_host/_cluster/health&#34; | jq -r &#39; &#34;集群状态: &#34; + .status + &#34; | 节点数: &#34; + (.number_of_nodes | tostring) + &#34; | 数据节点数: &#34; + (.number_of_data_nodes | tostring) + &#34; | 活跃分片: &#34; + (.active_shards | tostring) + &#34; | 重定位分片: &#34; + (.relocating_shards | tostring) + &#34; | 初始化分片: &#34; + (.initializing_shards | tostring) + &#34; | 未分配分片: &#34; + (.unassigned_shards | tostring) &#39; } # 主函数 main() { local es_host=&#34;${1:-localhost:9200}&#34; echo &#34;Elasticsearch系统监控报告 - $(date)&#34; echo &#34;==================================&#34; echo -e &#34;
